#include "xy_ist8310.h"
#include "xy_hal_sys.h"
#include <string.h>
static int ready(const xy_ist8310_t *d){return d&&d->initialized&&d->i2c_dev.base.initialized&&d->i2c_dev.i2c_handle;}
static xy_error_t wr(xy_ist8310_t*d,uint8_t r,uint8_t v){return xy_i2c_device_write_reg(&d->i2c_dev,r,&v,1);}
xy_error_t xy_ist8310_init(xy_ist8310_t*d,void*h){uint8_t id;xy_error_t r;if(!d||!h)return XY_DEVICE_INVALID_PARAM;memset(d,0,sizeof(*d));r=xy_i2c_device_init(&d->i2c_dev,h,XY_IST8310_ADDR,1000);if(r!=XY_DEVICE_OK)return r;r=xy_i2c_device_read_reg(&d->i2c_dev,XY_IST8310_REG_WHOAMI,&id,1);if(r==XY_DEVICE_OK&&id!=XY_IST8310_WHOAMI)r=XY_DEVICE_NOT_FOUND;if(r==XY_DEVICE_OK)r=wr(d,XY_IST8310_REG_CTRL1,XY_IST8310_CTRL1_CONTINUOUS_100HZ);if(r==XY_DEVICE_OK)r=wr(d,XY_IST8310_REG_CTRL2,XY_IST8310_CTRL2_ENABLE);if(r!=XY_DEVICE_OK){memset(d,0,sizeof(*d));return r;}d->initialized=1;return XY_DEVICE_OK;}
xy_error_t xy_ist8310_deinit(xy_ist8310_t*d){xy_error_t r;if(!ready(d))return XY_DEVICE_INVALID_PARAM;r=wr(d,XY_IST8310_REG_CTRL1,0);if(r!=XY_DEVICE_OK)return r;d->initialized=0;d->i2c_dev.base.initialized=0;d->i2c_dev.i2c_handle=NULL;return XY_DEVICE_OK;}
xy_error_t xy_ist8310_read(xy_ist8310_t*d,xy_ist8310_sample_t*s){uint8_t b[6];xy_ist8310_sample_t n;xy_error_t r;if(!ready(d)||!s)return XY_DEVICE_INVALID_PARAM;r=xy_i2c_device_read_reg(&d->i2c_dev,XY_IST8310_REG_DATA,b,6);if(r!=XY_DEVICE_OK)return r;n.raw_x=(int16_t)((uint16_t)b[0]|((uint16_t)b[1]<<8));n.raw_y=(int16_t)((uint16_t)b[2]|((uint16_t)b[3]<<8));n.raw_z=(int16_t)((uint16_t)b[4]|((uint16_t)b[5]<<8));n.timestamp=xy_hal_sys_get_tick_count();*s=n;d->sample=n;return XY_DEVICE_OK;}
